Ext.define('BNK.view.common.VersionInfomationManagementMViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.common.versioninfomationmanagementm',

    config: {
        viewId: 'VersionInfomationManagementM'
    },

    onGridSelect: function(dataview, selected, eOpts) {
        var me = this;

        // 버전선택시 현재앱버전과 서버앱버전이 상이할 경우, 업데이트 URL 표시
        if ('version' === selected[0].data.name) {
            if (Property.MOBILE_SERVER_VERSION > Property.MOBILE_VERSION) {
                Ext.Msg.confirm("안내", Ext.String.format('<div style="font-size : 15px; font-weight: bold">현재버전 {0}<br />최신버전 {1}</div><br /><br />업데이트하시겠습니까?', Property.MOBILE_VERSION, Property.MOBILE_SERVER_VERSION), function(buttonId) {
                if (buttonId == 'yes') {
                    //cordova.InAppBrowser.open(Property.UPDATE_URL, '_blank', 'location=yes');
                    location.href = Property.UPDATE_URL;
                }
            }, me);
        }
    }
    },

    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            store = vm.get('ExpNteConf01Store'),
            platform = null,
            model = null,
            uuid = null,
            version = null,
            manufacturer = null,
            serial = null;

        try {
            version = Property.MOBILE_VERSION;
            // 서버와 앱버전이 상이할 경우
            if (Property.MOBILE_VERSION != Property.MOBILE_SERVER_VERSION) {
                version += ' <img src="resources/images/new.png" />';
            }
            platform = device.platform + ' ' + device.version;
            model = device.model;
            uuid = device.uuid;
            manufacturer = device.manufacturer;
            serial = device.serial;
        } catch(error) {

        }

        store.add([
        {
            name  : 'version',
            text  : '버전',
            value : version
        },
        {
            name  : 'platform',
            text  : '플랫폼',
            value : platform
        }, {
            name  : 'model',
            text  : '모델명',
            value : model
        }, {
            name  : 'serial',
            text  : '모델번호',
            value : serial
        },
        // {
        //     name  : 'uuid',
        //     text  : '일련번호',
        //     value : uuid
        // },
        {
            name  : 'manufacturer',
            text  : '제조사',
            value : manufacturer
        }]);
    }

});